# Portable October 13 replication. Run from the repository root; see docs/SIMULATIONS.txt.
## Summary of the matched cap-sensitivity study (sim_cap_sensitivity.R). Output: results/simulation/tables/cap_sensitivity_application.csv,
## cap_sensitivity_simulation.csv (per set/scenario/cap/coefficient), cap_sensitivity_shifts.csv (per-dataset shifts vs cap 0.995).
args <- commandArgs(trailingOnly = TRUE); dir_in <- if (length(args) >= 1) args[1] else "results/simulation/cap_sensitivity"; sfx <- if (length(args) >= 2) args[2] else ""; tg <- readRDS("results/simulation/tables/expected_likelihood_targets.rds")$boundary; beta0 <- tg$generating$beta; bstar <- tg$beta_star; pn <- names(beta0); p <- 6; q_t <- qt(.975, 43); q_n <- qnorm(.975); caps <- c(0.99, 0.995, 0.999); options(width = 250)
pct <- function(d) list(lo = apply(d, 2, quantile, .025, na.rm = TRUE), hi = apply(d, 2, quantile, .975, na.rm = TRUE))
## application
a <- readRDS(file.path(dir_in, "application.rds"))$res; app <- do.call(rbind, lapply(a, function(r) { ci <- pct(r$draws); data.frame(cap = r$cap, parameter = pn, estimate = r$beta, loglik = r$loglik, status = r$status, max_phi = r$max_phi, se_model = r$se$model, se_cr0 = r$se$cr0, se_md = r$se$md, boot_lo = ci$lo, boot_hi = ci$hi, boot_constrained = mean(r$boot_status == "constrained"), boot_nonconv = mean(!(r$boot_status %in% c("interior", "constrained")))) }))
cat("APPLICATION (primary boundary analysis), by cap:\n"); print(app[app$parameter == "Diabetic", ], digits = 4, row.names = FALSE); print(unique(app[, c("cap", "loglik", "status", "max_phi", "boot_constrained", "boot_nonconv")]), digits = 6, row.names = FALSE); write.csv(app, sprintf("results/simulation/tables/cap_sensitivity_application%s.csv", sfx), row.names = FALSE)
## simulation sets
fs <- list.files(dir_in, "^(subset|stress)_tau.*\\.rds$", full.names = TRUE); zz <- lapply(fs, readRDS); rows <- list(); shifts <- list()
for (set in c("subset", "stress")) for (tau in c(0, 0.4)) { z <- zz[sapply(zz, function(x) x$set == set && x$tau == tau)]; if (!length(z)) next; target <- if (tau == 0) beta0 else bstar
  for (ci in seq_along(caps)) { cap <- caps[ci]; r <- lapply(z, function(x) x$res[[ci]]); est <- t(sapply(r, `[[`, "beta")); ll <- sapply(r, `[[`, "loglik"); ll995 <- sapply(z, function(x) x$res[[2]]$loglik); est995 <- t(sapply(z, function(x) x$res[[2]]$beta))
    lo <- t(sapply(r, function(x) pct(x$draws)$lo)); hi <- t(sapply(r, function(x) pct(x$draws)$hi)); lo995 <- t(sapply(z, function(x) pct(x$res[[2]]$draws)$lo)); hi995 <- t(sapply(z, function(x) pct(x$res[[2]]$draws)$hi))
    bc <- sapply(r, function(x) mean(x$boot_status == "constrained")); bn <- sapply(r, function(x) mean(!(x$boot_status %in% c("interior", "constrained"))))
    for (j in seq_len(p)) { row <- data.frame(set = set, tau = tau, cap = cap, parameter = pn[j], n = length(r), cap_active_fits = sum(sapply(r, `[[`, "status") == "constrained"), mean_est = mean(est[, j]), bias_vs_target = mean(est[, j]) - target[j], emp_sd = sd(est[, j]), mean_abs_shift_vs_995 = mean(abs(est[, j] - est995[, j])), max_abs_shift_vs_995 = max(abs(est[, j] - est995[, j])), mean_loglik_minus_995 = mean(ll - ll995))
      for (k in c("model", "cr0", "md")) { s <- sapply(r, function(x) x$se[[k]][j]); crit <- if (k == "model") q_n else q_t; row[[paste0("cov_", k)]] <- mean(abs(est[, j] - target[j]) <= crit * s, na.rm = TRUE); row[[paste0("medlen_", k)]] <- median(2 * crit * s, na.rm = TRUE) }
      row$cov_boot <- mean(target[j] >= lo[, j] & target[j] <= hi[, j]); row$medlen_boot <- median(hi[, j] - lo[, j]); row$mean_abs_endpoint_shift_vs_995 <- mean(abs(c(lo[, j] - lo995[, j], hi[, j] - hi995[, j]))); row$max_abs_endpoint_shift_vs_995 <- max(abs(c(lo[, j] - lo995[, j], hi[, j] - hi995[, j]))); row$boot_constrained_frac = mean(bc); row$boot_nonconv_frac = mean(bn); rows[[length(rows) + 1]] <- row } } }
df <- do.call(rbind, rows); rownames(df) <- NULL; write.csv(df, sprintf("results/simulation/tables/cap_sensitivity_simulation%s.csv", sfx), row.names = FALSE)
cat("\nSIMULATION SETS, Diabetic coefficient and aggregates:\n"); print(df[df$parameter == "Diabetic", c("set", "tau", "cap", "n", "cap_active_fits", "bias_vs_target", "emp_sd", "mean_abs_shift_vs_995", "max_abs_shift_vs_995", "mean_loglik_minus_995", "cov_model", "cov_cr0", "cov_md", "cov_boot", "medlen_cr0", "medlen_md", "medlen_boot", "max_abs_endpoint_shift_vs_995", "boot_constrained_frac", "boot_nonconv_frac")], digits = 3, row.names = FALSE)
cat("\nCoverage ranges over coefficients by set/tau/cap:\n"); ag <- aggregate(cbind(cov_model, cov_cr0, cov_md, cov_boot, max_abs_shift_vs_995, max_abs_endpoint_shift_vs_995) ~ set + tau + cap, df, function(x) paste(range(round(x, 3)), collapse = "-")); print(ag, row.names = FALSE)

## multistart record (if present)
ms <- do.call(rbind, lapply(c(file.path(dir_in, "application.rds"), fs), function(f) { z <- readRDS(f); if (is.null(z$multistart)) NULL else cbind(set = if (is.null(z$set)) "application" else z$set, tau = if (is.null(z$tau)) NA else z$tau, m = if (is.null(z$m)) 0 else z$m, z$multistart) }))
if (!is.null(ms)) { cat("\nMULTISTART REPLACEMENTS:\n"); print(aggregate(cbind(n = improvement > 0, median_improvement = improvement, max_improvement = improvement, max_beta_change = max_beta_change) ~ set + tau + cap + kind, ms, function(x) x[1])[0, ]); 
  for (k in unique(paste(ms$set, ms$tau))) { x <- ms[paste(ms$set, ms$tau) == k, ]; for (cap in caps) for (kind in c("original", "bootstrap")) { xx <- x[x$cap == cap & x$kind == kind, ]; if (nrow(xx)) cat(sprintf("  %-12s cap %.3f %-9s: %5d replaced | improvement median %.2f, max %.1f | max beta change %.3f | new status constrained %d\n", k, cap, kind, nrow(xx), median(xx$improvement), max(xx$improvement), max(xx$max_beta_change), sum(xx$new_status == "constrained"))) } }
  write.csv(ms, sprintf("results/simulation/tables/cap_sensitivity_multistart_record%s.csv", sfx), row.names = FALSE) }
